        return 'الحسين '+dam
    if line.startswith('AL HO'):
        return 'الهو '+dam
    if line.startswith('YA HUSSAIN'):
        return call
    if line.startswith(('HAIDER','R(a.s')):
        return 'حيدر حيدر حيدر حيدر' if line.startswith('HAIDER') else 'حيدرؑ حيدر حيدر'
    if line.startswith('HUSSA.)'):
        return 'حسين حسين'
    if '==' in line and line.startswith('HUSSAIN'):
        return 'حسين حسين حسين حسين'
    if line.startswith('NAHNU'):
        n=line.count('NAHNU')
        verses=[nahnu]*n
        if 'QULOO' in line:
            verses.insert(-1,'(قولوا قولوا)')
        return ' '.join(verses)
    if line.startswith('HUSSAIN HUSSAINAH'):
        ending=''
        if 'TAQABBAL' in line:
            ending=' (تقبّلت الزهراء)'
        if 'MAASHAA' in line:
            ending=' (ما شاء الله جلّ جلاله)'
        if 'RAZAIKUM' in line:
            ending=' (رضاكم الزهراء إن شاء الله جلّ جلاله)'
        if 'SAIYUKUM' in line:
            ending=' (سعيكم مشكوراً)'
        if 'QULOO' in line:
            ending=' (قولوا قولوا)'
        return chant.strip()+ending
    if line.startswith('HUSSAIN HUSSAIN HUSSIAN'):
        return 'حسين حسين حسين'+(' ما شاء الله جلّ جلاله' if 'MAASHAA' in line else '')
    if line=='QULO':
        return 'قولوا'
    raise ValueError(line)
verses=list(map(source,lines))
header=header.replace('language: \"Urdu\"\\nlang: \"ur\"\\ndirection: \"ltr\"', 'alternateTitle: \"Nahnu Ushaq-ul-Hussain\"\\nlanguage: \"Arabic\"\\nlang: \"ar\"\\ndirection: \"rtl\"').replace('tags: [\"noUrdu\"]','tags: []')
roman='\\n'.join('  '+line if line else '' for line in lines)
